import{_ as o,o as r,c as l,ag as i}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"天涯神贴合集 · 学习总纲","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/00_学习总纲.md","filePath":"topics/tianya/notes/00_学习总纲.md"}'),n={name:"topics/tianya/notes/00_学习总纲.md"};function s(a,t,e,u,g,q){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="天涯神贴合集-·-学习总纲" tabindex="-1">天涯神贴合集 · 学习总纲 <a class="header-anchor" href="#天涯神贴合集-·-学习总纲" aria-label="Permalink to &quot;天涯神贴合集 · 学习总纲&quot;">​</a></h1><blockquote><p>2026-11-06 通读完毕：138 帖 / 约 20 万页 / 提取文本 77MB / 10 份分类笔记（见本目录）。 本总纲是跨类别的沉淀：那些帖子作为一个整体在说什么、哪些经受住了 15 年检验、对今天的我们还有什么用。</p></blockquote><hr><h2 id="一、作为整体的合集在讲什么" tabindex="-1">一、作为整体的合集在讲什么 <a class="header-anchor" href="#一、作为整体的合集在讲什么" aria-label="Permalink to &quot;一、作为整体的合集在讲什么&quot;">​</a></h2><p>这是 <strong>2005–2020 年中国民间智识的化石层</strong>：</p><ul><li><strong>上半场（2005–2015）</strong>：全民议题是&quot;房价会不会跌&quot;，多空论战本质是财富分配之争；</li><li><strong>中场（2015–2019）</strong>：股灾、杠杆、裁员、中美贸易战——焦虑从&quot;买不买得起&quot;变成&quot;会不会被甩下&quot;；</li><li><strong>下半场（2019–2020）</strong>：通缩叙事登场，滞胀恐惧、债务周期、&quot;周期的尾声&quot;。</li><li>穿插其间的是另一半中国：殡葬师、刑警、DNA 鉴定师、赌场荷官、96 岁的老千——<strong>正史不写的人，把正史没写的部分写完了</strong>。</li></ul><h2 id="二、十个经受住检验的结论-跨帖交叉验证" tabindex="-1">二、十个经受住检验的结论（跨帖交叉验证） <a class="header-anchor" href="#二、十个经受住检验的结论-跨帖交叉验证" aria-label="Permalink to &quot;二、十个经受住检验的结论（跨帖交叉验证）&quot;">​</a></h2><ol><li><strong>预测命中率取决于预测对象</strong>（10 批笔记共同结论）：制度/结构性判断约 7-8 成准，方向性宏观约五成，点位与择时约三成。赢的人都在回答&quot;谁在决策、他怕什么&quot;，输的人都在喊自己的信仰。</li><li><strong>共同分析框架真实有效</strong>：货币蓄水池论（flp713 首创）→ 外储之锚（&quot;外储是因，房产是果&quot;）→ 债务-通缩切换（2014 年提出，2021–2026 完全验证）。这条主线串起了 KK、第三元、曼因斯坦、老仇。</li><li><strong>最大的集体盲点</strong>：高估政策速度、低估路径依赖——房产税、宅基地入市、人民币国际化全部比预期慢一个数量级；崩盘时点集体早 3 年。<strong>&quot;方向对、时点错&quot;是这个群体最体面的失败方式</strong>。</li><li><strong>带条件的判断活下来了，无条件信仰死了</strong>：&quot;泡沫不破除非经济危机&quot;（海男）、&quot;十年内四环八万&quot;（北望帝都，2021 兑现）活着；&quot;永远涨&quot;&quot;准确率100%&quot;死了。2021 年是所有房价叙事的实验终点。</li><li><strong>杠杆是绞肉机</strong>：南侠1987 两度千万归零、股灾强平者众；幸存短线客的共同点只有三条——轻仓、只做最强、止损不商量。</li><li><strong>在中国，政策是第一变量</strong>：润土三次创业败于规则而非市场； kkndme 说&quot;调控防的是金融风险不是价格&quot;——理解文件比理解K线重要。</li><li><strong>灵异是糖衣，行业干货才是药</strong>：纯写实的悬案/检察官帖照样红。天涯&quot;职业+灵异&quot;配方的秘密=职业细节是信任状 + 悬而不解释是连载钩子。</li><li><strong>骗局的内核永远一样</strong>：先取信、后收网、贪念即杠杆。96 岁老千和招商主管自白跨越 80 年互相印证——防骗四件套（搜差评、看实物、算利益流向、认出托儿）至今通用。</li><li><strong>玄学帖的成色分层</strong>：把&quot;改命&quot;讲成&quot;改行为&quot;的（写在脸上的风水）最靠谱；给具体点位的（汇率贬到8、纳指8500见顶）全军覆没——玄学和经济预测 obeys 同一条规律。</li><li><strong>这套社区再也不会有了</strong>：订阅制、算法推荐、实名制杀死了&quot;匿名陌生人认真写三万字&quot;的生态。这 20 万页是那个生态最后的沉积岩。</li></ol><h2 id="三、最值得重读-top10-按-重读价值-时间-排序" tabindex="-1">三、最值得重读 TOP10（按&quot;重读价值/时间&quot;排序） <a class="header-anchor" href="#三、最值得重读-top10-按-重读价值-时间-排序" aria-label="Permalink to &quot;三、最值得重读 TOP10（按&quot;重读价值/时间&quot;排序）&quot;">​</a></h2><ol><li><strong>KK三部曲</strong>（kkndme，2010）——利益分析法教科书，房价问题的底层代码</li><li><strong>曼因斯坦·大神预言神准</strong>（2016）——游资锁定、庞氏债务，最冷静的顶部观察</li><li><strong>冰冷的经济真相</strong>（flp713，2011）——货币蓄水池论原典，通胀叙事的起点</li><li><strong>市场心理研究</strong>（205，1475页）——用贪嗔痴慢疑讲交易心理，本合集最被低估的干货</li><li><strong>中国式骗局大全</strong>（96岁老千）——防骗终身教材，出版名《江湖三十年》</li><li><strong>社会不教，精英不讲</strong>（152）——职场平台论与&quot;利用价值&quot;定价</li><li><strong>我是一名警察</strong>（128，11017页）——职业细节+时代案件，信息密度最高的故事帖</li><li><strong>赌场二年 / 赌坛风云</strong>——负期望世界的活体解剖</li><li><strong>宝钗比黛玉大八岁</strong>（190）——红学考据的天花板级文本细读</li><li><strong>太平洋战争</strong>（194，8920页）——民间军事写作的技术巅峰</li></ol><h2 id="四、给-master-的三条阅读路线" tabindex="-1">四、给 master 的三条阅读路线 <a class="header-anchor" href="#四、给-master-的三条阅读路线" aria-label="Permalink to &quot;四、给 master 的三条阅读路线&quot;">​</a></h2><ul><li><strong>看预言复盘</strong>（1-2天）：01 笔记 → 03 笔记 → 04 笔记，对照原帖：KK → 曼因斯坦 → 老江南 → 周期的尾声</li><li><strong>学安身立命</strong>（3-5天）：06 笔记 → 05 笔记，原帖：社会不教 → 市场心理研究 → 虚拟货币的秘密</li><li><strong>纯消遣</strong>：07/08 笔记挑菜 → 十宗罪 / 民调局 / 我是一名警察</li></ul><h2 id="五、我的-学习-沉淀-供以后的对话调用" tabindex="-1">五、我的&quot;学习&quot;沉淀（供以后的对话调用） <a class="header-anchor" href="#五、我的-学习-沉淀-供以后的对话调用" aria-label="Permalink to &quot;五、我的&quot;学习&quot;沉淀（供以后的对话调用）&quot;">​</a></h2><ul><li>以后 master 聊房价/经济周期/投资，我可以直接调用这批框架与案例（含出处帖号）</li><li>聊小说/灵异/出版，我知道每部作品的出版与影视化情况</li><li>笔记共 10 份（约 6 万字），本总纲是索引；原文本在 /tmp/thunder/texts/（重启即失，可由 PDF 重提取）</li></ul><hr><p><em>生成：2026-11-06，10 路子代理精读 + 主会话综合。所有观点均出自原帖正文，预测对照以 2026-11 现实为准。</em></p>',16)])])}const c=o(n,[["render",s]]);export{d as __pageData,c as default};
